import {
  Contract,
  TransactionBuilder,
  BASE_FEE,
  Address,
  nativeToScVal,
  scValToNative,
  rpc,
} from "@stellar/stellar-sdk";
import { stellarConfig, STELLAR_TX_TIMEOUT_SECONDS, STELLAR_CONFIRMATION_TIMEOUT_MS, STELLAR_INCLUSION_FEE } from "../constants.js";
import type { StellarSigner, Network } from "../types.js";
import { SubmissionTimeoutError } from "../errors.js";

function getServer(network: Network, rpcUrl?: string): rpc.Server {
  return new rpc.Server(rpcUrl ?? stellarConfig(network).sorobanRpcUrl);
}

async function signTransaction(
  xdr: string,
  signer: StellarSigner,
  network: Network,
): Promise<string> {
  const passphrase = stellarConfig(network).networkPassphrase;
  if (signer.signTransaction) {
    return signer.signTransaction(xdr, passphrase);
  }
  if (signer.keypair) {
    const tx = TransactionBuilder.fromXDR(xdr, passphrase);
    tx.sign(signer.keypair);
    return tx.toXDR();
  }
  throw new Error("StellarSigner must provide either a keypair or a signTransaction function");
}

/**
 * Simulates, prepares, signs, and submits a Soroban contract invocation, then
 * polls the RPC server until the transaction is confirmed. Returns the tx hash.
 */
async function invokeContract(
  contractId: string,
  method: string,
  args: ReturnType<typeof nativeToScVal>[],
  signer: StellarSigner,
  network: Network,
  rpcUrl?: string,
): Promise<string> {
  const server = getServer(network, rpcUrl);
  const account = await server.getAccount(signer.publicKey);
  const contract = new Contract(contractId);

  const builtTx = new TransactionBuilder(account, {
    fee: STELLAR_INCLUSION_FEE,
    networkPassphrase: stellarConfig(network).networkPassphrase,
  })
    .addOperation(contract.call(method, ...args))
    .setTimeout(STELLAR_TX_TIMEOUT_SECONDS)
    .build();

  const prepared = await server.prepareTransaction(builtTx);
  const signedXdr = await signTransaction(prepared.toXDR(), signer, network);
  const signedTx = TransactionBuilder.fromXDR(signedXdr, stellarConfig(network).networkPassphrase);

  const sendResult = await server.sendTransaction(signedTx);
  if (sendResult.status === "ERROR") {
    throw new Error(`Stellar transaction submission failed: ${JSON.stringify(sendResult.errorResult)}`);
  }

  return pollTransactionStatus(server, sendResult.hash);
}

async function pollTransactionStatus(server: rpc.Server, hash: string): Promise<string> {
  const deadline = Date.now() + STELLAR_CONFIRMATION_TIMEOUT_MS;
  while (Date.now() < deadline) {
    const result = await server.getTransaction(hash);
    if (result.status === "SUCCESS") return hash;
    if (result.status === "FAILED") {
      throw new Error(`Stellar transaction ${hash} failed`);
    }
    await new Promise((resolve) => setTimeout(resolve, 2000));
  }
  // The transaction was broadcast (this hash came from a successful sendTransaction);
  // confirmation did not arrive within the timeout. This differs from never having been
  // submitted, so the hash is surfaced for callers to act on instead of being discarded
  // in a bare error.
  throw new SubmissionTimeoutError(`Timed out waiting for Stellar transaction ${hash} to confirm`, hash);
}

/**
 * Approves Stellar's TokenMessengerMinter to pull USDC from the signer via the
 * SEP-41 token's transfer_from, mirroring the ERC20 approve step CCTP needs on
 * EVM chains. Required before deposit_for_burn, which otherwise fails with
 * "not enough allowance to spend".
 */
export async function approveUsdc(
  amount: bigint,
  signer: StellarSigner,
  network: Network,
  rpcUrl?: string,
): Promise<string> {
  const contractId = stellarConfig(network).usdc;
  const minterId = stellarConfig(network).tokenMessengerMinter;
  const minterAddress = new Address(minterId);

  return invokeContract(
    contractId,
    "approve",
    [minterAddress.toScVal(), nativeToScVal(amount, { type: "i128" })],
    signer,
    network,
    rpcUrl,
  );
}

/**
 * Burns USDC on Stellar via the SEP-41 token's transfer_from, mirroring the
 * ERC20 burn step CCTP needs on EVM chains.
 */
export async function burnUsdcOnStellar(
  amount: bigint,
  destinationDomain: number,
  destinationAddress: string,
  forwardHook: string,
  signer: StellarSigner,
  network: Network,
  rpcUrl?: string,
): Promise<string> {
  const contractId = stellarConfig(network).tokenMessengerMinter;
  const usdcId = stellarConfig(network).usdc;
  const usdcAddress = new Address(usdcId);

  return invokeContract(
    contractId,
    "deposit_for_burn",
    [
      usdcAddress.toScVal(),
      nativeToScVal(amount, { type: "i128" }),
      nativeToScVal(destinationDomain, { type: "u32" }),
      nativeToScVal(destinationAddress, { type: "bytes" }),
      nativeToScVal(forwardHook, { type: "bytes" }),
    ],
    signer,
    network,
    rpcUrl,
  );
}

/**
 * Mints USDC on Stellar and forwards it to the recipient.
 */
export async function mintAndForwardOnStellar(
  message: string,
  attestation: string,
  recipient: string,
  network: Network,
  rpcUrl?: string,
): Promise<string> {
  const contractId = stellarConfig(network).cctpForwarder;
  const recipientAddress = new Address(recipient);

  // The CCTP Forwarder contract requires a signer to invoke it, but the actual
  // signer doesn't matter since the contract itself handles the minting and
  // forwarding logic. We use a dummy keypair for this purpose.
  const dummySigner = {
    publicKey: "GAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAV",
    keypair: Address.random().keypair(),
  };

  return invokeContract(
    contractId,
    "mint_and_forward",
    [
      nativeToScVal(message, { type: "bytes" }),
      nativeToScVal(attestation, { type: "bytes" }),
      recipientAddress.toScVal(),
    ],
    dummySigner, // Dummy signer, as the contract handles permissions
    network,
    rpcUrl,
  );
}

export type StellarRecipientStatus = {
  exists: boolean;
  hasTrustline: boolean;
  ready: boolean;
};

/**
 * Checks if a Stellar recipient account exists and has a trustline for USDC.
 * Returns `{ exists: false, hasTrustline: false, ready: false }` if the account
 * does not exist. Throws an error for RPC or network failures.
 */
export async function checkStellarRecipientReady(
  recipient: string,
  network: Network,
  rpcUrl?: string,
): Promise<StellarRecipientStatus> {
  const server = getServer(network, rpcUrl);
  try {
    const account = await server.getAccount(recipient);
    // Check if the account has a trustline for the USDC asset
    // The asset code for USDC on Stellar is "USDC" and the issuer is the SAC ID.
    const usdcAssetId = stellarConfig(network).usdc;
    const hasTrustline = account.balances.some(
      (balance) =>
        balance.asset_type === "credit_alphanum4" &&
        balance.asset_code === "USDC" &&
        balance.asset_issuer === usdcAssetId,
    );
    return { exists: true, hasTrustline, ready: hasTrustline };
  } catch (e: any) {
    // Stellar SDK throws an error with message "The resource does not exist" for unfunded accounts.
    // Other errors (network, RPC 5xx) should propagate.
    if (e.message && typeof e.message === 'string' && e.message.includes("The resource does not exist")) {
      return { exists: false, hasTrustline: false, ready: false };
    }
    // Re-throw other errors as they indicate an infrastructure problem
    throw e;
  }
}
