describe("checkStellarRecipientReady", () => {
  const recipientPublicKey = Keypair.random().publicKey();
  const network = "testnet";
  const usdcAssetId = STELLAR_TESTNET.usdc;

  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("should return exists: true and hasTrustline: true if account exists with USDC trustline", async () => {
    mockGetAccount.mockResolvedValueOnce({
      id: recipientPublicKey,
      balances: [
        { asset_type: "native", balance: "10.0" },
        { asset_type: "credit_alphanum4", asset_code: "USDC", asset_issuer: usdcAssetId, balance: "100.0" },
      ],
    });

    const status = await checkStellarRecipientReady(recipientPublicKey, network);
    expect(status).toEqual({ exists: true, hasTrustline: true, ready: true });
    expect(mockGetAccount).toHaveBeenCalledWith(recipientPublicKey);
  });

  it("should return exists: true and hasTrustline: false if account exists without USDC trustline", async () => {
    mockGetAccount.mockResolvedValueOnce({
      id: recipientPublicKey,
      balances: [
        { asset_type: "native", balance: "10.0" },
        { asset_type: "credit_alphanum4", asset_code: "OTHER", asset_issuer: "GA123...", balance: "50.0" },
